import 'server-only';
import { createHash } from 'node:crypto';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { StudioError, windsorMounted } from '../../studio/storage';

// VOLTA Editor — Edit mode storage. The boot SSD is nearly full: every generated byte (uploads, caches, saved
// sequences, exports when Windsor is unplugged) lives under ~/Documents/PROJECTS/ErisMornCloud/volta/editor/.
// Exports prefer the Windsor drive. Every bulk write checks free space first (>= 3 GiB must remain).

export const NLE_ROOT = path.join(os.homedir(), 'Documents/PROJECTS/ErisMornCloud/volta/editor');
export const UPLOADS_DIR = path.join(NLE_ROOT, 'uploads');
export const CACHE_DIR = path.join(NLE_ROOT, 'cache');
export const PROJECTS_DIR = path.join(NLE_ROOT, 'projects');
export const TRASH_DIR = path.join(PROJECTS_DIR, '.trash');
export const LOCAL_EXPORTS_DIR = path.join(NLE_ROOT, 'exports');
export const WINDSOR_EXPORTS_DIR = '/Volumes/Windsor/VOLTA/editor/exports';

export const FFMPEG = '/opt/homebrew/bin/ffmpeg';
export const FFPROBE = '/opt/homebrew/bin/ffprobe';

export const GiB = 1024 ** 3;
/** Free space that must REMAIN on a volume after a bulk write. */
export const MIN_REMAIN_BYTES = 3 * GiB;

export { StudioError as NleError };

export async function ensureDir(dir: string): Promise<string> {
  await fs.mkdir(dir, { recursive: true });
  return dir;
}

/** Where finished exports go: Windsor when it is really mounted, else the ErisMornCloud exports folder. */
export async function exportsDir(): Promise<string> {
  return (await windsorMounted()) ? WINDSOR_EXPORTS_DIR : LOCAL_EXPORTS_DIR;
}

/** Free bytes on the volume holding `p` (walks up to the nearest existing ancestor). */
export async function freeBytes(p: string): Promise<number> {
  let dir = p;
  for (;;) {
    try {
      const s = await fs.statfs(dir);
      return Number(s.bavail) * Number(s.bsize);
    } catch (err) {
      const parent = path.dirname(dir);
      if ((err as NodeJS.ErrnoException).code !== 'ENOENT' || parent === dir) throw err;
      dir = parent;
    }
  }
}

/** Throws a 507 when writing `bytes` into `dir` would leave fewer than 3 GiB free on that volume. */
export async function requireSpace(dir: string, bytes: number, what: string): Promise<number> {
  const free = await freeBytes(dir);
  if (free - bytes < MIN_REMAIN_BYTES) {
    throw new StudioError(
      `Not enough disk space for ${what}: ${(free / GiB).toFixed(1)} GiB free on the volume holding ${tildePath(dir)}` +
        (bytes > 0 ? ` and this needs about ${(bytes / GiB).toFixed(2)} GiB` : '') +
        `; at least ${MIN_REMAIN_BYTES / GiB} GiB must remain free.`,
      507,
    );
  }
  return free;
}

export const tildePath = (p: string) => (p.startsWith(os.homedir()) ? `~${p.slice(os.homedir().length)}` : p);

export const sha1 = (s: string, n = 20) => createHash('sha1').update(s).digest('hex').slice(0, n);

/** Write a file atomically (tmp + rename) in the same directory. */
export async function writeAtomic(file: string, data: string | Buffer): Promise<void> {
  await ensureDir(path.dirname(file));
  const tmp = `${file}.${process.pid}.${Date.now().toString(36)}.tmp`;
  try {
    await fs.writeFile(tmp, data);
    await fs.rename(tmp, file);
  } catch (err) {
    await fs.rm(tmp, { force: true }).catch(() => undefined);
    throw err;
  }
}

/** Keep the cache bounded: when it holds more than `maxFiles` files, delete the oldest (by mtime) down to 80 %. */
export async function pruneCache(maxFiles = 3000): Promise<void> {
  try {
    const names = (await fs.readdir(CACHE_DIR, { withFileTypes: true })).filter((d) => d.isFile()).map((d) => d.name);
    if (names.length <= maxFiles) return;
    const stats = await Promise.all(
      names.map(async (n) => {
        const st = await fs.stat(path.join(CACHE_DIR, n)).catch(() => null);
        return { n, m: st?.mtimeMs ?? 0 };
      }),
    );
    stats.sort((a, b) => a.m - b.m);
    for (const s of stats.slice(0, names.length - Math.floor(maxFiles * 0.8))) await fs.rm(path.join(CACHE_DIR, s.n), { force: true });
  } catch {
    // best effort
  }
}

/** Tiny async semaphore (bounds concurrent ffmpeg helpers). */
export function limiter(max: number) {
  let active = 0;
  const queue: (() => void)[] = [];
  return async function run<T>(fn: () => Promise<T>): Promise<T> {
    if (active >= max) await new Promise<void>((r) => queue.push(r));
    active++;
    try {
      return await fn();
    } finally {
      active--;
      queue.shift()?.();
    }
  };
}
